def esc(v):
    v = v.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    v = v.replace("'", "\\'").replace('"', '\\"').replace("\n", "\\n").replace("@", "\\@")
    return v

def write(path, idx):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    lines = ['<?xml version="1.0" encoding="utf-8"?>', "<resources>"]
    for k, vals in S.items():
        v = vals[idx]
        extra = ""
        if k == "app_name": extra = ' translatable="false"'
        # strings with several % signs need formatted="false"-safe handling: we use positional args, so fine.
        lines.append(f'    <string name="{k}"{extra}>{esc(v)}</string>')
    lines.append("</resources>")
    open(path, "w", encoding="utf-8").write("\n".join(lines) + "\n")

root = sys.argv[1]
write(f"{root}/values/strings.xml", 0)
write(f"{root}/values-en/strings.xml", 1)
write(f"{root}/values-ar/strings.xml", 2)
print(len(S), "string keys written")
